head.script:
scwin.screenId = "uldmgt50014";

///////// 1. 변수 및 선언 영역 /////////


scwin.tmp = "null";

scwin.em = undefined;


///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.x_path = undefined; try { scwin.x_path = /* sdd-asis-lifecycle:begin x_path — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.tmp.split(",")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50014' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50014.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.getEM
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getEM = function () {
    /* sdd-asis-lifecycle:begin getEM — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const obj = $c.util.getComponent('xpathList');
    let cellObj;
    let data;
    let value = "";
    let htmlContent = "null";
    for (let i = 0; i < obj.rows.length; i++) {
        cellObj = obj.rows[i];
        data = cellObj.cells[1];
        value = data.outerText;
        for (let k = 0; k < scwin.x_path.length; k++) {
            if (scwin.x_path[k].indexOf(value) > 0) {
                const em = cellObj.cells[0].outerText;
                const cd_nm = scwin.Hex4ToStr(scwin.x_path[k].substring(0, scwin.x_path[k].indexOf(":")));
                htmlContent = htmlContent.replace(em, "<font color='red'>" + cd_nm + "</font>");
                $c.util.getComponent('txt_formView').setValue(htmlContent);
                break;
            }
        }
    }
    (!obj ? console.warn('[sdd] 표시 전환 대상 미해결: obj') : (("none") === 'none' ? (obj.hide ? obj.hide() : void 0) : (obj.show ? obj.show() : void 0)));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.Hex4ToStr
 * @author Inswave
 * @date 2026. 09. 29
 * @param encode_data
 * @returns
 * @hidden N
*/
scwin.Hex4ToStr = function (encode_data) {
    /* sdd-asis-lifecycle:begin Hex4ToStr — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let newData = "";
    let iNo = 0;
    for (let i = 0; i < encode_data.length / 4; i++) {
        const str = encode_data.substr(iNo, 4);
        const iNum = parseInt('0x' + str);
        const strChar = String.fromCharCode(iNum);
        newData += strChar;
        iNo = iNo + 4;
    }
    return newData;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.showForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.showForm = function (obj) {
    /* sdd-asis-lifecycle:begin fn_ShowForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.setPageFrameSrc($c.win.getFrame(), '/formprocslist/formprocslist.xml') + dma_pageContext.get("formCd") + "&formVer=" + dma_pageContext.get("formVer") + "" + "&lang=" + obj.getValue();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.printForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.printForm = function () {
    /* sdd-asis-lifecycle:begin printForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.popupPrint();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.copyXpath
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.copyXpath = function (obj) {
    /* sdd-asis-lifecycle:begin copyXpath — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    navigator.clipboard.setData("Text", "/xbrli:xbrl" + obj.xpath);
    /* sdd-asis-lifecycle:end */
};
